export const TOPIC_SEED_MAP: Record<string, SeedTest> = Object.fromEntries(
  TOPIC_SEED_TESTS.map(t => [t.id, t])
);

// seed_topik1_full — reading + listening birlashtirilgan (30 savol)
export function buildSeedFull(id: string): SeedTest | null {
  if (id === "seed_topik1_full") {
    const r = TOPIC_SEED_MAP.seed_topik1_reading;
    const l = TOPIC_SEED_MAP.seed_topik1_listening;
    if (!r || !l) return null;
    return {
      id: "seed_topik1_full",
      title: "TOPIK I — Full Mock (30 savol)",
      level: "TOPIK I",
      type: "Full",
      time: "80 daq",
      questions: [...r.questions, ...l.questions],
    };
  }
  return TOPIC_SEED_MAP[id] ?? null;
}
